#!/usr/bin/env python3
"""Record toolchain, source repairs, workload inputs and effective local topology."""
from pathlib import Path
import json,hashlib,subprocess,platform,time
R=Path(__file__).resolve().parent;W=R.parents[1]/'webridge'
def run(cmd):return subprocess.check_output(cmd,text=True,stderr=subprocess.STDOUT).strip()
files=[R/'Dockerfile.build',R/'Dockerfile.network',R/'build_toolchain.sh',R/'repair_upstream.py',R/'paper_control.py',R/'paper_run_pair.py',R/'paper-audit/recipe.json',R/'paper-driver/paper-repair-receipt.json',R/'java/PaperCompilerServer.java',W/'Application/my-blog/target/my-blog-4.0.0-SNAPSHOT.jar',R/'paper-driver/build/libs/webench-1.0-SNAPSHOT.jar']
receipt={'recorded_utc':time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime()),'artifact_commit':run(['git','-C',str(W),'rev-parse','HEAD']),'host':platform.node(),'platform':platform.platform(),'source_diff':run(['git','-C',str(W),'diff']),'upstream_build_tools_revision':(R/'upstream-jdk-revision.txt').read_text().strip(),'sha256':{str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in files if p.exists()},'mysql_version':run(['docker','exec','jac-webridge-paper-mysql5725','mysql','-uroot','-N','-e','SELECT VERSION();']),'db_container_limits':json.loads(run(['docker','inspect','-f','{{json .HostConfig}}','jac-webridge-paper-mysql5725'])),'rtt_receipt':(R/'paper/ping-rtt.txt').read_text(),'network_qdisc':(R/'paper/netem.txt').read_text(),'application_affinity':'0-3,10-13','database_affinity':'4-7,14-17','offline_compiler_affinity':'9,19','client_affinity':'8,18','topology':'one physical host with four process/container CPU partitions; differs from four separate paper machines','local_memory':'DB cgroup16GiB; online heap-Xmx16g; online process memory is not cgroup-limited','workload':'equal GI/BD/EB with5000blogs and valid1..5000IDs; latent API mix paper unspecified, throughput equal paper specified'}
(R/'paper/provenance.json').write_text(json.dumps(receipt,indent=2)+'\n');print(R/'paper/provenance.json')
